entry:
Angle_Init_EN   = 1;
Init_Done       = 0;
id_init_ref     = Id_Init_Target;
Init_State_Num  = 2;
during:
Angle_Init_EN = 1;
Init_Done     = 0;
id_init_ref   = Id_Init_Target;

RAMP_DOWN_ID
entry:
Angle_Init_EN   = 1;
Init_Done       = 0;
id_init_ref     = Id_Init_Target;
Init_State_Num  = 3;
during:
Angle_Init_EN = 1;
Init_Done     = 0;
id_init_ref = id_init_ref - Id_Init_Target/Id_Release_Ramp_Ticks;
if (id_init_ref < 0)
    id_init_ref = 0;
end
Theta_Offset_auto = theta_offset_mem;

DONE
entry:
Angle_Init_EN   = 0;
Init_Done       = 1;
id_init_ref     = 0;
Init_State_Num  = 4;
during:
Angle_Init_EN = 0;
Init_Done = 1;
id_init_ref = 0;
Init_State_Num = 4;
Theta_Offset_auto = theta_offset_mem;

[after(Hold_Ticks, tick)]
{x_align_mm_latch = x_mm;
theta_offset_mem = mod(theta_align_const - 2*pi*x_align_mm_latch/Tau_e_mm, 2*pi);
Theta_Offset_auto = theta_offset_mem;}

function y = theta_to_u16(theta)
t=mod(theta,2*pi);
n=floor(t*65536/(2*pi)+0.5);
if n>=65536, n=0; end
y=uint16(n);
end

function [x_ref_mm,vdc,load_N,Close_Loop_EN,Position_Loop_EN,PWM_EN,v_ref_cmd,id_ref_cmd,iq_test_mode,iq_test_ref,PI_Reset_EN] = Simple_Host(t, Host_Enable_Schedule, Host_Speed_mmps, Host_Id_A, Host_Iq_Test_Mode, Host_Iq_A, Host_PI_Reset_EN, Host_Start_s, Host_Target_mm, Udc, Host_Load_N, Host_Traj_Vmax, Host_Traj_Amax, Host_Traj_Jmax, Host_Speed_Ramp_s)
% Smooth acceleration - constant speed - smooth deceleration.
x_ref_mm=pmlsm_scurve_profile(t-Host_Start_s,Host_Target_mm,Host_Traj_Vmax,Host_Traj_Amax,Host_Traj_Jmax,Host_Speed_Ramp_s);
r=min(max((t-Host_Start_s)/max(Host_Speed_Ramp_s,1e-6),0),1);
v_ref_cmd=Host_Speed_mmps*(10*r^3-15*r^4+6*r^5);
vdc=Udc; load_N=Host_Load_N;
Close_Loop_EN=0; Position_Loop_EN=0; PWM_EN=0;
for k=1:size(Host_Enable_Schedule,1)
 if t>=Host_Enable_Schedule(k,1)
  Close_Loop_EN=double(Host_Enable_Schedule(k,2)~=0);
  Position_Loop_EN=double(Host_Enable_Schedule(k,3)~=0);
  PWM_EN=double(Host_Enable_Schedule(k,4)~=0);
 end
end
id_ref_cmd=Host_Id_A;
iq_test_mode=Host_Iq_Test_Mode; iq_test_ref=Host_Iq_A;
PI_Reset_EN=Host_PI_Reset_EN;
end

